 "content": "from collections import Counter


def transform(grid):
    """Move all non-background cells down by one row."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    bg = Counter(value for row in grid for value in row).most_common(1)[0][0]
    out = [[bg for _ in row] for row in grid]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != bg and r + 1 < len(grid):
                out[r + 1][c] = value
    return out


